update ui.dashboardresultset set idashboardid=37 where idashboardresultsetid=22;

UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{
    "Account":"SELECT  count(RT.IRULEID) AS \\"count\\", R.VCRULENAME AS \\"name\\" FROM analytics.RULE_TRIGGERED AS RT JOIN MASTERS.RULES AS R ON R.IRULEID = RT.IRULEID WHERE RT.itenantid = :tenantid and RT.vcpayeraccountexternalid = :Address group by RT.IRULEID, R.VCRULENAME;",
     "VPA": "SELECT count(RT.IRULEID) AS \\"count\\", R.VCRULENAME AS \\"name\\" FROM analytics.RULE_TRIGGERED AS RT JOIN MASTERS.RULES AS R ON R.IRULEID = RT.IRULEID WHERE RT.vcpayeraddr = :Address and RT.itenantid = :tenantid group by RT.IRULEID, R.VCRULENAME;"
}'::text WHERE
idashboardqueryid = 49;

UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{
    "Account":"WITH  profile AS (SELECT * FROM profiles.account pv left join masters.accounts v on v.iaccountid = pv.iaccountid where v.itenantid = :tenantid and v.vcexternalaccountid = :Address  order by tdate desc limit 1) SELECT X.* FROM (VALUES (''Days In System'',(select CASE WHEN  cast(val->''daysInTheSystem''->>''payer'' as int) IS NOT NULL and cast(val->''daysInTheSystem''->>''payee'' as int) IS NOT NULL THEN CASE WHEN cast(val->''daysInTheSystem''->>''payer'' as int) > cast(val->''daysInTheSystem''->>''payee'' as int) THEN val->''daysInTheSystem''->>''payer'' else val->''daysInTheSystem''->>''payee'' END WHEN cast(val->''daysInTheSystem''->>''payer'' as int) IS NOT NULL THEN val->''daysInTheSystem''->>''payer'' else val->''daysInTheSystem''->>''payee''  END from profile)), (''Total Value As Payer'',(SELECT val->''totalValue''->>''payer'' FROM profile)), (''Average Value As Payer'',(SELECT val->''avgValue''->''p90d''->>''payer'' FROM profile)), (''Total Value As Payee'',(SELECT val->''totalValue''->>''payee'' FROM profile)), (''Average Value As Payee'',(SELECT val->''avgValue''->''p90d''->>''payee'' FROM profile)) ) AS X (\\"name\\",\\"value\\");",
    "VPA": "WITH profile AS (SELECT *  FROM profiles.vpa pv left join masters.vpa v on v.ivpaid = pv.ivpaid where v.itenantid = :tenantid and v.vcexternaladdressid = :Address order by tdate desc limit 1) SELECT X.* FROM (VALUES (''Days In System'',(select CASE WHEN  cast(val->''daysInTheSystem''->>''payer'' as int) IS NOT NULL and cast(val->''daysInTheSystem''->>''payee'' as int) IS NOT NULL THEN CASE WHEN cast(val->''daysInTheSystem''->>''payer'' as int) > cast(val->''daysInTheSystem''->>''payee'' as int) THEN val->''daysInTheSystem''->>''payer'' else val->''daysInTheSystem''->>''payee'' END WHEN cast(val->''daysInTheSystem''->>''payer'' as int) IS NOT NULL THEN val->''daysInTheSystem''->>''payer'' else val->''daysInTheSystem''->>''payee''  END from profile)), (''Total Value As Payer'',(SELECT val->''totalValue''->>''payer'' FROM profile)), (''Average Value As Payer'',(SELECT val->''avgValue''->''p90d''->>''payer'' FROM profile)), (''Total Value As Payee'',(SELECT val->''totalValue''->>''payee'' FROM profile)), (''Average Value As Payee'',(SELECT val->''avgValue''->''p90d''->>''payee'' FROM profile)) ) AS X (\\"name\\", \\"value\\");"
}'::text WHERE
idashboardqueryid = 58;

